set-variable.value:
@{
      // Primary: derive from APIM product name.
      var product = context.Product?.Name ?? string.Empty;
      var p = product.ToLowerInvariant();
      if (p.Contains("premium")) { return "premium"; }
      if (p.Contains("standard")) { return "standard"; }
      if (p.Contains("free")) { return "free"; }
      // Fallback for demo subscription keys without a mapped product.
      return context.Request.Headers.GetValueOrDefault("x-consumer-tier", "free").ToLowerInvariant();
  }
